SELECT os.order_id AS orderId, os.spectator_id AS id, sp.name AS name, sp.id_type AS idType, sp.id_card AS idCard FROM tb_order_spectator os LEFT JOIN tb_spectator sp ON sp.id = os.spectator_id WHERE os.delete_token = 0 AND os.order_id IN
#{id}
ORDER BY os.id ASC

SELECT ot.order_id AS orderId, ot.id AS id, ot.ticket_name AS ticketName, ot.spectator_id AS spectatorId, ot.spectator_name AS spectatorName, ot.check_status AS checkStatus, ot.seat_info AS seatInfo, ot.qr_code AS qrCode FROM tb_order_ticket ot WHERE ot.order_id IN
#{id}
ORDER BY ot.id ASC
